$z=[IO.Compression.ZipFile]::Open($work,'Update')
try{
 function ReadXml($part){$reader=[IO.StreamReader]::new($z.GetEntry($part).Open());try{return ,([xml]$reader.ReadToEnd())}finally{$reader.Dispose()}}
 function SaveXml($part,$xml){$entry=$z.GetEntry($part);if(-not $entry){$entry=$z.CreateEntry($part)};$stream=$entry.Open();$stream.SetLength(0);$writer=[IO.StreamWriter]::new($stream,[Text.UTF8Encoding]::new($false));try{$xml.Save($writer)}finally{$writer.Dispose()}}
 function Binary($part,$file){$old=$z.GetEntry($part);if($old){$old.Delete()};$stream=$z.CreateEntry($part).Open();try{$bytes=[IO.File]::ReadAllBytes($file);$stream.Write($bytes,0,$bytes.Length)}finally{$stream.Dispose()}}
