 $w='http://schemas.openxmlformats.org/wordprocessingml/2006/main';$a='http://schemas.openxmlformats.org/drawingml/2006/main';$r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
 $n=[Xml.XmlNamespaceManager]::new($d.NameTable);$n.AddNamespace('w',$w);$n.AddNamespace('a',$a);$n.AddNamespace('r',$r);$n.AddNamespace('wp','http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing')
 function Txt($node){($node.SelectNodes('.//w:t',$n)|ForEach-Object InnerText)-join ''}
 function Put($p,$value){$ts=$p.SelectNodes('.//w:t',$n);$ts[0].InnerText=$value;foreach($t in @($ts|Select-Object -Skip 1)){$t.InnerText=''}}
 function Attr($node,$name,$value){$null=$node.SetAttribute($name,$w,[string]$value)}
 $body=$d.SelectSingleNode('//w:body',$n);$paras=@($body.SelectNodes('w:p',$n))
 $heading=@($paras|Where-Object {(Txt $_).Trim() -eq 'Use Case Diagram'})
 $caption=@($paras|Where-Object {(Txt $_).Trim() -match '^Figure 4\.'})
 $end=@($paras|Where-Object {(Txt $_).Trim().StartsWith('End-to-end system flow.')})
 if($heading.Count -ne 1 -or $caption.Count -ne 1 -or $end.Count -ne 1){throw 'Ambiguous use-case section boundaries'}
 $pictures=[Collections.Generic.List[object]]::new();$p=$heading[0].NextSibling
 while($p -and -not [object]::ReferenceEquals($p,$caption[0])){if($p.SelectSingleNode('.//a:blip',$n)){$pictures.Add($p)};$p=$p.NextSibling}
 if(-not $p -or $pictures.Count -ne 1){throw 'Expected one use-case image before the caption'}
 $picture=$pictures[0];$tablesBefore=(@($d.SelectNodes('//w:tbl',$n)|ForEach-Object OuterXml))-join ''
 $old=[Collections.Generic.List[object]]::new();$p=$caption[0].NextSibling
 while($p -and -not [object]::ReferenceEquals($p,$end[0])){if($p.LocalName -ne 'p' -or $p.SelectSingleNode('.//w:drawing|w:pPr/w:sectPr',$n)){throw 'Unexpected content in use-case explanation'};$old.Add($p);$p=$p.NextSibling}
 if(-not $p -or $old.Count -lt 3){throw 'Use-case explanation not found'}
 $template=@($old|Where-Object {(Txt $_).Trim()})[0]
 $blip=$picture.SelectSingleNode('.//a:blip',$n);$rid=$blip.GetAttribute('embed',$r);$rel=@($rels.DocumentElement.ChildNodes|Where-Object Id -eq $rid)[0]
 if(-not $rel){throw 'Use-case image relationship missing'}
 $rel.SetAttribute('Target','media/irongrind-use-cases.png')
 Binary 'word/media/irongrind-use-cases.png' (Join-Path $figures '04-use-cases.png')
 Binary 'word/media/irongrind-use-cases.svg' (Join-Path $figures '04-use-cases.svg')
 $svgRid='rIdIronGrindUseCaseSVG';$svgRel=@($rels.DocumentElement.ChildNodes|Where-Object Id -eq $svgRid)
 if(-not $svgRel){$svgRel=$rels.CreateElement('Relationship',$rels.DocumentElement.NamespaceURI);$svgRel.SetAttribute('Id',$svgRid);$svgRel.SetAttribute('Type',$r+'/image');$svgRel.SetAttribute('Target','media/irongrind-use-cases.svg');$null=$rels.DocumentElement.AppendChild($svgRel)}
 foreach($e in @($blip.SelectNodes('a:extLst/a:ext[@uri="{96DAC541-7B7A-43D3-8B79-37D633B846F1}"]',$n))){$null=$e.ParentNode.RemoveChild($e)}
 $list=$blip.SelectSingleNode('a:extLst',$n);if(-not $list){$list=$d.CreateElement('a','extLst',$a);$null=$blip.AppendChild($list)}
 $ext=$d.CreateElement('a','ext',$a);$ext.SetAttribute('uri','{96DAC541-7B7A-43D3-8B79-37D633B846F1}');$sb=$d.CreateElement('asvg','svgBlip','http://schemas.microsoft.com/office/drawing/2016/SVG/main');$null=$sb.SetAttribute('embed',$r,$svgRid);$null=$ext.AppendChild($sb);$null=$list.AppendChild($ext)
 if(-not @($ct.DocumentElement.ChildNodes|Where-Object Extension -eq 'svg')){$default=$ct.CreateElement('Default',$ct.DocumentElement.NamespaceURI);$default.SetAttribute('Extension','svg');$default.SetAttribute('ContentType','image/svg+xml');$null=$ct.DocumentElement.AppendChild($default)}
 $svg=[xml](Get-Content -Raw -LiteralPath (Join-Path $figures '04-use-cases.svg'));$view=@($svg.DocumentElement.GetAttribute('viewBox') -split '\s+'|ForEach-Object {[double]$_})
 $cx=[long](6.3*914400);$cy=[long]($cx*$view[3]/$view[2]);foreach($e in $picture.SelectNodes('.//wp:extent|.//a:xfrm/a:ext',$n)){$e.SetAttribute('cx',"$cx");$e.SetAttribute('cy',"$cy")}
 $info=$picture.SelectSingleNode('.//wp:docPr',$n);$info.SetAttribute('name','IronGrind UML Use-Case Diagram');$info.SetAttribute('descr','Nine function-level use cases, three labeled head-and-shoulders actor icons, and twenty-two plain associations. All three actors participate in User Management within role-specific limits.')
 Put $caption[0] 'Figure 4. UML Use-Case Diagram'
 foreach($item in @($heading[0],$picture,$caption[0])){
  $pr=$item.SelectSingleNode('w:pPr',$n);if(-not $pr){$pr=$d.CreateElement('w','pPr',$w);$null=$item.PrependChild($pr)}
  foreach($e in @($pr.SelectNodes('w:keepNext|w:pageBreakBefore',$n))){$null=$pr.RemoveChild($e)}
  if(-not [object]::ReferenceEquals($item,$caption[0])){$null=$pr.AppendChild($d.CreateElement('w','keepNext',$w))}
  if([object]::ReferenceEquals($item,$heading[0])){$null=$pr.AppendChild($d.CreateElement('w','pageBreakBefore',$w))}
  $sp=$pr.SelectSingleNode('w:spacing',$n);if(-not $sp){$sp=$d.CreateElement('w','spacing',$w);$null=$pr.AppendChild($sp)};Attr $sp 'before' 0;Attr $sp 'after' 80;Attr $sp 'line' 240;Attr $sp 'lineRule' 'auto'
  $ind=$pr.SelectSingleNode('w:ind',$n);if(-not $ind){$ind=$d.CreateElement('w','ind',$w);$null=$pr.AppendChild($ind)};foreach($name in @('left','right','firstLine')){Attr $ind $name 0}
  if(-not [object]::ReferenceEquals($item,$heading[0])){$jc=$pr.SelectSingleNode('w:jc',$n);if(-not $jc){$jc=$d.CreateElement('w','jc',$w);$null=$pr.AppendChild($jc)};Attr $jc 'val' 'center'}
  $order=@('pStyle','keepNext','keepLines','pageBreakBefore','widowControl','numPr','tabs','spacing','ind','jc','outlineLvl','rPr','sectPr','pPrChange')
  foreach($child in @($pr.ChildNodes|Sort-Object {$i=[Array]::IndexOf($order,$_.LocalName);if($i -lt 0){9}else{$i}})){$null=$pr.AppendChild($child)}
 }
 $texts=@(
 'Figure 4 presents the IronGrind Membership and Operations Management System as a UML use-case diagram organized around the nine main functions in the functional requirements. The use cases are User Login, Membership Application, User Management, Renewals, QR Attendance, Product & Inventory, Sales, Generate Reports, and Activity Logs. Each oval represents one function-level capability, while the enclosing rectangle identifies the system boundary. The three external actors are Member / Applicant, Authorized Staff, and Administrator. They are represented by labeled head-and-shoulders icons outside the boundary. The diagram shows which actors participate in each function, while the accompanying explanations distinguish the particular tasks and permissions available to each role.',
 'The diagram contains twenty-two solid actor-to-use-case associations: six for Member / Applicant, seven for Authorized Staff, and nine for Administrator. These plain lines indicate participation; they do not show data movement, screen navigation, or the chronological order of operations. Crossings do not create additional relationships. No include, extend, or actor-generalization relationship is asserted. Because the nine ovals are broad functions, an association does not give an actor every action within that function. User Management is the clearest example: all three actors participate, but they perform different operations on different permitted information.',
 'Member / Applicant represents a prospective applicant and an existing member at their respective stages of interaction with the gym. This actor is associated with User Login, Membership Application, User Management, Renewals, QR Attendance, and Product & Inventory. Application submission and application-status information relate to the registration stage, whereas the registered member uses personal membership and self-service features. Access to protected member information remains subject to the implemented account and membership checks. The actor is not associated with Sales, Generate Reports, or Activity Logs, because these are operator or administrator functions rather than member purchasing or oversight privileges.',
 'Authorized Staff participates in User Login, Membership Application, User Management, Renewals, QR Attendance, Product & Inventory, and Sales. These associations cover authorized request review, attendance handling, supported counter membership services, access to the sales catalog, product-sale recording, and review of the operator''s own product sales. They do not give staff general access to member profiles, inventory maintenance, staff-account administration, phone-pairing administration, administrator reports, or activity logs. Administrator is associated with all nine functions and performs the operational and supervisory actions permitted by the administrator workflow. Its broader participation still respects the implemented restriction that member personal profiles are viewed without editing their personal details.',
 'User Login verifies an account and establishes access to the interface permitted for its role and account state. All three actors participate in this function. A successful credential check is followed by the applicable role and active-account checks; the existence of a login association does not authorize access to another role''s operations. Authentication and authorization are prerequisites to protected actions even though the diagram does not draw an include relationship from every other oval to User Login.',
 'Membership Application covers online registration submission and its review. The applicant supplies the required registration information and receives the recorded application status. An authorized staff member or administrator reviews the limited pending-request details and records an approval or rejection. Approval is performed through an authorized server-side operation that rechecks the operator and pending state, prevents repeat processing, and creates or links the appropriate member and membership transaction records. The applicant''s association represents submitting and checking the request, while the operator associations represent review and processing. They are different responsibilities within one functional area, not interchangeable permissions.',
 'User Management includes role-specific account, personal-profile, and counter membership responsibilities. Administrators view member profiles without editing their personal details and control supported staff-account access. Members alone update their own permitted personal-profile details. Staff register walk-in members and process direct renewals or active-plan changes using limited lookup information. Those counter operations create or update the records required for the authorized membership transaction; they do not provide a general member-profile viewer or an existing-profile editing function. All three User Management associations are therefore intentional and match the functional requirement. The administrator and member associations must not be interpreted as granting the same personal-information editing rights.',
 'Renewals allows a member to submit an online renewal request and obtain its status, while authorized staff and administrators review and approve or reject the request. Approval updates the linked membership, records the applicable renewal history and transaction, and saves the review decision. The online request workflow is distinct from a direct counter renewal, which is described under the operator responsibilities of User Management. Both workflows concern membership continuation, but the broad Renewals association does not let a member approve a request or directly change the recorded membership dates.',
 'QR Attendance has different member and operator uses. The member displays their own QR code and views their own attendance history. Authorized staff and administrators scan the member QR and retrieve permitted visit information. The attendance service checks the member and current visit state before recording a check-in or check-out with its timestamp and operator. The member''s association does not mean that a member can record attendance for themselves or another person. Administrator-managed mobile pairing supports the scanning arrangement, while staff scanning remains subject to operator authorization rather than permission to administer paired devices.',
 'Product & Inventory combines product viewing with administrator maintenance. Members browse the active product catalog, and staff read the product information permitted for their sales tasks. Administrators maintain supported product details, prices, units, stock, and active state. All three actors are connected because they participate in this functional area, but only the administrator maintains inventory. Catalog access does not establish an online member checkout, authorize a stock adjustment, or permit a staff member to change product information.',
 'Sales is associated with Administrator and Authorized Staff. Authorized operators enter the relevant customer and product-sale details, while the system validates the item, sale unit, quantity, price, and available stock, records the sale and line items, and applies the corresponding stock deduction. Staff may review their own product-sale records; the association does not imply unrestricted access to other operators'' sales. Members are not connected to Sales because the implemented workflow records transactions through an operator. A saved system transaction or its internal receipt_number reference does not establish that the system issues a customer receipt.',
 'Generate Reports and Activity Logs are administrator-only use cases. Generate Reports retrieves supported operational information for the selected report and its available preview or export. Activity Logs retrieves recorded events using the supported filters and paging controls. Neither function is associated with Member / Applicant or Authorized Staff. Reading an event in the log is also distinct from performing the action described by that event; the log viewer does not execute membership changes, inventory changes, account changes, or pairing controls.',
 'The use-case diagram and the DFD describe complementary aspects of the same nine-function system. Figure 4 identifies actor participation and functional scope, while the DFD identifies the information exchanged with processes and stores. The ERD and data dictionary describe the persistent records affected by the authorized operations. Their shared function names support consistency across the chapter, but a diagram association is not an access-control mechanism. Database policies, active-role checks, authorized functions, and server-side services enforce the restrictions described here. The system-flow discussion that follows explains how these responsibilities operate together in the implemented workflows.'
 )
 foreach($text in $texts){
  $p=$d.CreateElement('w','p',$w);$sourcePr=$template.SelectSingleNode('w:pPr',$n);if($sourcePr){$null=$p.AppendChild($sourcePr.CloneNode($true))}
  $pr=$p.SelectSingleNode('w:pPr',$n);if($pr){foreach($e in @($pr.SelectNodes('w:keepNext|w:pageBreakBefore',$n))){$null=$pr.RemoveChild($e)}}
  $run=$d.CreateElement('w','r',$w);$rp=$d.CreateElement('w','rPr',$w);$fonts=$d.CreateElement('w','rFonts',$w);foreach($name in @('ascii','hAnsi','cs','eastAsia')){Attr $fonts $name 'Times New Roman'};$null=$rp.AppendChild($fonts);$sz=$d.CreateElement('w','sz',$w);Attr $sz 'val' 24;$null=$rp.AppendChild($sz);$null=$run.AppendChild($rp)
  $t=$d.CreateElement('w','t',$w);$t.InnerText=$text;$null=$run.AppendChild($t);$null=$p.AppendChild($run);$null=$body.InsertBefore($p,$end[0])
 }
 foreach($p in $old){$null=$body.RemoveChild($p)}
 if($tablesBefore -cne ((@($d.SelectNodes('//w:tbl',$n)|ForEach-Object OuterXml))-join '')){throw 'A requirements or dictionary table changed'}
